use super::*;
use crate::pet_data::publication::restore::{CONFIG_INDEPENDENT_REVIEW,CONFIG_REVIEW,independent};
use crate::pet_runtime::restoration::{IndependentFixtureRecord,fixture_prepared_seed_denies_old_ids,fixture_fresh_independent_goal};
#[path="restored_retained_independent_transaction_tests.rs"]mod retained_tests;
fn prepared()->Fixture{
 let mut f=Fixture::with_history(false,true);let before=fs::read(f.config().join(CONFIG_REVIEW)).unwrap();let r=Review::capture(f.owner.claim(&f.target.layout()).unwrap(),f.target.layout(),&f.workspace,&f.id,Mode::Resume).unwrap().authority().unwrap();let fp=r.preview().unwrap()["fingerprint"].as_str().unwrap().to_owned();r.apply(&fp).unwrap();
 let r=Review::capture(f.owner.claim(&f.target.layout()).unwrap(),f.target.layout(),&f.workspace,&f.id,Mode::Resume).unwrap().configuration().unwrap();let v=r.preview().unwrap();assert_eq!(v["schemaVersion"],3);assert_eq!(v["history"],"noOriginalAuthority");assert_eq!(v["independent"]["originalAuthorityPresent"],false);r.apply(v["fingerprint"].as_str().unwrap()).unwrap();assert_eq!(fs::read(f.config().join(CONFIG_REVIEW)).unwrap(),before);f.choices.inspection_receipt=hash_bytes(&fs::read(f.config().join(CONFIG_INDEPENDENT_REVIEW)).unwrap());f
}
fn old_goal(f:&Fixture)->IndependentFixtureRecord{let path=fs::read_dir(f.config().join("payload/pet-runtime-v1")).unwrap().map(|e|e.unwrap().path()).find(|p|p.file_name().unwrap().to_str().unwrap().starts_with("g-")).unwrap();serde_json::from_slice(&fs::read(path).unwrap()).unwrap()}
#[test]fn independent_admission4_preserves_absent_original_authority_and_denies_old_ids_before_new_consent(){
 let f=prepared();let old=old_goal(&f);let seed=f.config().join(independent::JOB).join("seed");let key_hash=hash_bytes(&fs::read(seed.join(".key.json")).unwrap());let custody=super::private_tree_bytes(&f.config().join(independent::JOB));let r=f.review().unwrap();assert_eq!(r.manifest.version,4);assert_eq!(r.manifest.profile_version().unwrap(),2);assert_eq!(r.manifest.admission_version().unwrap(),4);let v=r.preview().unwrap();assert_eq!(v["independent"]["originalAuthorityPresent"],false);r.apply(v["fingerprint"].as_str().unwrap()).unwrap();
 let record:Value=serde_json::from_slice(&fs::read(f.config().join(publication::ADMITTED)).unwrap()).unwrap();assert_eq!(record["version"],4);assert!(record.get("epoch").is_none());assert_eq!(record["independent"]["originalAuthorityPresent"],false);assert!(!f.config().join(JOB).join("originals/config/pet-runtime-consent-v1").exists());assert!(super::private_tree_bytes(&f.config().join(independent::JOB))==custody,"preparation custody changed");
 let storage=f.active().unwrap().into_storage().unwrap();let paths=storage.paths().unwrap();assert_eq!(hash_bytes(&fs::read(paths.config.join("pet-runtime-consent-v1/.key.json")).unwrap()),key_hash);assert!(fixture_prepared_seed_denies_old_ids(&paths.config.join("pet-runtime-consent-v1"),&old));let h=storage.restored_history().unwrap().unwrap();assert!(h.conversation_allowed("codex","old-current",None).is_err());assert!(h.native_session_allowed("codex","old-native").is_err());assert_eq!(fs::read(paths.data.join("inbox/independent-unknown.bin")).unwrap(),b"uncertain consumption remains unknown");let fresh=fixture_fresh_independent_goal(&paths.config.join("pet-runtime-v1"),&paths.config.join("pet-runtime-consent-v1"));assert_ne!(fresh.id,old.id);storage.current().unwrap();drop(storage);assert!(f.active().is_ok());
}
#[test]fn independent_each_publication_boundary_reuses_same_key_originals_and_exact_choices(){
 for cut in [Step::OriginalsReady,Step::AuthorityStaged(0),Step::AuthorityPublished,Step::Staged(0),Step::Changed(0),Step::BeforeAdmission,Step::Admitted]{let f=prepared();let key_hash=hash_bytes(&fs::read(f.config().join(independent::JOB).join("seed/.key.json")).unwrap());let a=f.review().unwrap();let fp=a.fingerprint.clone();assert!(a.apply_using(&fp,|s|if s==cut{Err(Error::Unavailable)}else{Ok(())}).is_err(),"{cut:?}");if cut!=Step::Admitted{assert!(f.active().is_err());}let a=f.review().unwrap();let fp=a.fingerprint.clone();a.apply(&fp).unwrap();let storage=f.active().unwrap().into_storage().unwrap();assert_eq!(hash_bytes(&fs::read(storage.paths().unwrap().config.join("pet-runtime-consent-v1/.key.json")).unwrap()),key_hash);assert!(!f.config().join(JOB).join("originals/config/pet-runtime-consent-v1").exists());}
}
#[test]fn independent_wrong_hash_old_inspection_changed_choices_or_claim_never_publish_a_key(){
 for action in ["hash","oldReceipt","choices","claim"]{let mut f=prepared();let a=f.review().unwrap();let mut fp=a.fingerprint.clone();if action=="hash"{fp="0".repeat(64);}if action=="claim"{f.owner.release();}if action=="hash"||action=="claim"{assert!(a.apply(&fp).is_err());}else{drop(a);if action=="oldReceipt"{f.choices.inspection_receipt=hash_bytes(&fs::read(f.config().join(CONFIG_REVIEW)).unwrap());assert!(f.review().is_err());}else{let a=f.review().unwrap();let fp=a.fingerprint.clone();a.apply_using(&fp,|s|if s==Step::OriginalsReady{Err(Error::Unavailable)}else{Ok(())}).unwrap_err();f.choices.grants.clear();assert!(f.review().is_err());}}assert!(!f.config().join("payload/pet-runtime-consent-v1").exists());assert!(!f.config().join(publication::ADMITTED).exists());}
}
#[test]fn independent_custody_originals_and_published_key_tamper_are_retained_and_refused(){
 for name in [".restore-authority/seed/.key.json",".restore-authority/ready.json",".restore-authority/generation.json",".restore-activation/originals/config/settings.json","payload/pet-runtime-consent-v1/.key.json"]{let f=prepared();let a=f.review().unwrap();let fp=a.fingerprint.clone();a.apply_using(&fp,|s|if s==Step::AuthorityPublished{Err(Error::Unavailable)}else{Ok(())}).unwrap_err();let p=f.config().join(name);fs::write(&p,b"private injected corrupt data").unwrap();if let Ok(a)=f.review(){let fp=a.fingerprint.clone();assert!(a.apply(&fp).is_err(),"{name}");}assert!(f.active().is_err());assert_eq!(fs::read(&p).unwrap(),b"private injected corrupt data");assert!(!f.config().join(publication::ADMITTED).exists());}
}
#[test]fn independent_revoked_native_owner_during_key_copy_blocks_all_later_effects(){
 for cut in [Step::OriginalsReady,Step::AuthorityStaged(0),Step::AuthorityPublished,Step::BeforeAdmission]{let f=prepared();let a=f.review().unwrap();let fp=a.fingerprint.clone();assert!(a.apply_using(&fp,|s|{if s==cut{f.owner.release();}Ok(())}).is_err());assert!(!f.config().join(publication::ADMITTED).exists());if cut==Step::OriginalsReady{assert!(!f.config().join("payload/pet-runtime-consent-v1").exists());}}
}
#[test]fn independent_opened_restart_and_native_ack_keep_new_goal_out_of_old_snapshot_with_archive_offline(){
 let f=prepared();let a=f.review().unwrap();let original_fp=a.fingerprint.clone();a.apply(&original_fp).unwrap();let storage=f.active().unwrap().into_storage().unwrap();let paths=storage.paths().unwrap();let fresh=fixture_fresh_independent_goal(&paths.config.join("pet-runtime-v1"),&paths.config.join("pet-runtime-consent-v1"));storage.current().unwrap();drop(storage);fs::rename(&f.workspace,f.source.0.join("external-archive-offline")).unwrap();let active=f.active().unwrap();assert_eq!(active.activation_ack(&f.id,&f.choices,Some(&original_fp)).unwrap()["runtimeActivationAvailable"],true);let storage=active.into_storage().unwrap();let bytes=fs::read(storage.paths().unwrap().config.join("pet-runtime-v1").join(format!("{}.json",fresh.id))).unwrap();let current:IndependentFixtureRecord=serde_json::from_slice(&bytes).unwrap();assert_eq!(current.id,fresh.id);storage.current().unwrap();
}
#[test]fn independent_portable_backup_and_next_epoch_preserve_provenance_key_and_all_prior_denials(){
 exercise_portable_next(prepared());
}
fn exercise_portable_next(f:Fixture){
 let expected=f.review().unwrap().manifest.independent.unwrap();let old=old_goal(&f);f.admit();let storage=f.active().unwrap().into_storage().unwrap();let paths=storage.paths().unwrap();let fresh=fixture_fresh_independent_goal(&paths.config.join("pet-runtime-v1"),&paths.config.join("pet-runtime-consent-v1"));let key_hash=hash_bytes(&fs::read(paths.config.join("pet-runtime-consent-v1/.key.json")).unwrap());fs::write(paths.data.join("assistant/conversations.json"),br#"{"version":4,"pets":{"codex":{"id":"second-independent-current","created":3,"updated":4,"messages":[],"session":{"id":"second-independent-native","cwd":"/private-fixture","full_access":false},"tasks":[]}},"archives":{}}"#).unwrap();drop(storage);
 let workspace=portable_workspace(&f);let id=portable(&f,&workspace);let inspected=staging::inspect_current(&workspace,&id).unwrap();assert_eq!(inspected.source_payload_depth,Some(1));let target=Temp::new();let layout=target.layout();for p in [&layout.legacy_config,&layout.legacy_data]{fs::DirBuilder::new().recursive(true).mode(0o700).create(p).unwrap();}let e=EpochFixture{source:f,target,owner:Harness::new(),workspace,id};let a=e.review(Mode::Fresh).unwrap();let fp=a.preview().unwrap()["fingerprint"].as_str().unwrap().to_owned();a.apply(&fp).unwrap();let a=e.review(Mode::Resume).unwrap().authority().unwrap();let fp=a.preview().unwrap()["fingerprint"].as_str().unwrap().to_owned();a.apply(&fp).unwrap();let a=e.review(Mode::Resume).unwrap().configuration().unwrap();let v=a.preview().unwrap();let receipt=a.apply(v["fingerprint"].as_str().unwrap()).unwrap();let mut c=e.source.choices.clone();c.inspection_receipt=receipt["receiptHash"].as_str().unwrap().into();let a=Activation::capture(e.owner.claim(&e.target.layout()).unwrap(),e.target.layout(),&e.workspace,&e.id,c.clone()).unwrap();let v=a.preview().unwrap();a.apply(v["fingerprint"].as_str().unwrap()).unwrap();let storage=Active::open(e.owner.claim(&e.target.layout()).unwrap(),e.target.layout()).unwrap().into_storage().unwrap();let paths=storage.paths().unwrap();assert_eq!(hash_bytes(&fs::read(paths.config.join("pet-runtime-consent-v1/.key.json")).unwrap()),key_hash);assert!(fixture_prepared_seed_denies_old_ids(&paths.config.join("pet-runtime-consent-v1"),&old));assert!(fixture_prepared_seed_denies_old_ids(&paths.config.join("pet-runtime-consent-v1"),&fresh));let h=storage.restored_history().unwrap().unwrap();for id in ["old-current","second-independent-current"]{assert!(h.conversation_allowed("codex",id,None).is_err());}let nested:Value=serde_json::from_slice(&fs::read(e.target.layout().config().join("payload/.admitted.json")).unwrap()).unwrap();assert_eq!(nested["version"],4);assert_eq!(nested["independent"]["originalAuthorityPresent"],false);
 let nested:independent::operational::Custody=serde_json::from_value(nested["independent"].clone()).unwrap();assert_eq!(nested,expected);
}
